package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.domain.respository.SheetsRepository
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftForm
import org.koin.core.component.KoinComponent


class AddCraftedItem(private val repository: SheetsRepository) : KoinComponent {

    suspend operator fun invoke(form: ItemCraftForm): Result<SheetEntryData> {
        return repository.addCraftedItem(form)
    }
}