package com.coding.va.selfhelp.data.respository


import com.coding.va.selfhelp.data.mapper.cardCodeToEntryData
import com.coding.va.selfhelp.data.mapper.toSheetsEntry
import com.coding.va.selfhelp.data.models.GoogleSheetsRequest
import com.coding.va.selfhelp.data.network.GoogleSheetsService
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.model.EntryType
import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.domain.respository.SheetsRepository
import com.coding.va.selfhelp.presentation.components.plinfield.model.plinToText
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftForm
import com.coding.va.selfhelp.presentation.screens.craft.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.craft.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueForm
import com.coding.va.selfhelp.presentation.screens.imbue.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.imbue.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.model.VortexItemCardDisplay
import com.coding.va.selfhelp.presentation.screens.recharge.model.RechargeForm
import com.coding.va.selfhelp.presentation.screens.recharge.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.recharge.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.datetime.Clock
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json


class SheetsRepositoryImp(
    private val service: GoogleSheetsService,
) : SheetsRepository {

    override suspend fun setPrinted(entry: SheetEntryData): Result<Unit> {
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    "true"
                )
            )
        )

        return service.updatePrinted(body, entry).map {
            entry
        }
    }

    override suspend fun addCraftedItem(form: ItemCraftForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createSheetEntry(EntryType.CRAFT_ITEM).getOrThrow()
            createCraftedItem(form, entry).getOrThrow()
        }
    }

    override suspend fun addImbue(form: ImbueForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = if (form.isPerson) {
                createSheetEntry(EntryType.IMBUE_PERSON).getOrThrow()
            } else {
                createSheetEntry(EntryType.IMBUE_ITEM).getOrThrow()
            }
            createImbue(form, entry).getOrThrow()
        }
    }

    override suspend fun addRecharge(form: RechargeForm): Result<SheetEntryData> {
        return Result.runCatching {
            val entry = createSheetEntry(EntryType.RECHARGE_ITEM).getOrThrow()
            createRechargeItem(form, entry).getOrThrow()
        }
    }

    override suspend fun getPrintData(cardCode: String): Result<SuccessData> {
        return Result.runCatching {
            val entryData = cardCode.cardCodeToEntryData()
            val result = service.getSheetEntry(entryData).getOrThrow()
            if (cardCode == result.values[0][1]) {
                SuccessData(
                    Json.decodeFromString<VortexItemCardDisplay>(result.values[0][2]),
                    SheetEntryData(
                        rowNumber = entryData.rowNumber,
                        itemId = result.values[0][5],
                        getCardCode = result.values[0][1],
                        type = entryData.type,
                        alreadyPrinted = result.values[0][4].toBoolean(),
                    )
                )
            } else {
                throw Exception("Card code mismatch $cardCode - ${result.values[0][1]}")
            }
        }
    }

    private suspend fun createSheetEntry(type: EntryType): Result<SheetEntryData> {
        return service.createSheetEntry(type).map { it.toSheetsEntry(type) }
    }

    private suspend fun createCraftedItem(
        form: ItemCraftForm,
        entry: SheetEntryData
    ): Result<SheetEntryData> {
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    Clock.System.now().toString(),
                    entry.getCardCode,
                    Json.encodeToString(form.toVortexCard(entry.itemId)),
                    getPlatform().displayName,
                    "false",
                    entry.itemId,
                    form.name,
                    form.description,
                    form.imbueCap,
                    form.toResourcesText(),
                    form.notes,
                )
            )
        )

        return service.updateSheetEntry(body, entry).map {
            entry
        }
    }

    private suspend fun createImbue(
        form: ImbueForm,
        entry: SheetEntryData
    ): Result<SheetEntryData> {
        val vortexCard = form.toVortexCard(entry.itemId)
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    Clock.System.now().toString(),
                    entry.getCardCode,
                    Json.encodeToString(form.toVortexCard(entry.itemId)),
                    getPlatform().displayName,
                    "false",
                    entry.itemId,
                    (form.targetItin ?: form.targetPlin?.plinToText().orEmpty()),
                    vortexCard.power.orEmpty(),
                    form.toResourcesText(),
                    form.notes,
                )
            )
        )
        return service.updateSheetEntry(body, entry).map {
            entry
        }
    }

    private suspend fun createRechargeItem(
        form: RechargeForm,
        entry: SheetEntryData
    ): Result<SheetEntryData> {
        val body = GoogleSheetsRequest(
            values = listOf(
                listOf(
                    Clock.System.now().toString(),
                    entry.getCardCode,
                    Json.encodeToString(form.toVortexCard(entry.itemId)),
                    getPlatform().displayName,
                    "false",
                    entry.itemId,
                    form.targetItin,
                    form.toResourcesText(),
                    form.notes,
                )
            )
        )
        return service.updateSheetEntry(body, entry).map {
            entry
        }
    }
}