package com.coding.va.selfhelp.data.models

import com.coding.va.selfhelp.domain.model.EntryType
import kotlinx.serialization.Serializable

@Serializable
data class GoogleSheetsEntryResponse(
    val range: String?,
    val majorDimension: String,
    val values: List<List<String>>
)

@Serializable
data class SheetsAppendResponse(
    val spreadsheetId: String?,
    val tableRange: String?,
    val updates: UpdateDetails?
