@Serializable
data class UpdateDetails(
    val spreadsheetId: String,
    val updatedRange: String,
    val updatedRows: Int,
    val updatedColumns: Int,
    val updatedCells: Int
)

data class EntryData(
    val rowNumber: String,
    val type: EntryType,
)