package com.coding.va.selfhelp.presentation.screens.landing.model

import com.coding.va.selfhelp.presentation.screens.mainscreen.model.TaskType

sealed class LandingScreenEvent() {
    data class Navigate(val type: TaskType) : LandingScreenEvent()

    data class MenuChange(val menu: MenuDisplay) : LandingScreenEvent()

    data class CardCode(val code: String) : LandingScreenEvent()

    data object PrintCard : LandingScreenEvent()

    data object DismissError : LandingScreenEvent()

    data object MenuSave : LandingScreenEvent()

    data object MenuLock : LandingScreenEvent()
}