package com.coding.va

import androidx.compose.ui.ExperimentalComposeUiApi
import androidx.compose.ui.window.CanvasBasedWindow
import com.coding.va.selfhelp.App
import com.coding.va.selfhelp.di.initKoin
import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.FirebaseOptions
import dev.gitlive.firebase.initialize
import dev.gitlive.firebase.remoteconfig.remoteConfig
import kotlinx.browser.window
import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.launch
import org.jetbrains.skiko.wasm.onWasmReady
import org.koin.compose.koinInject
import kotlin.time.Duration.Companion.minutes

@OptIn(ExperimentalComposeUiApi::class)
fun main() {
    setupFirebase()
    initKoin()
    onWasmReady {
        CanvasBasedWindow(title = "Vortex self help", canvasElementId = "ComposeTarget") {
            App(koinInject(), { controller ->
                window.addEventListener("popstate", {
                    controller.popBackStack()
                })
            })
        }
    }
}

private fun setupFirebase() {
    Firebase.initialize(
        options = FirebaseOptions(
            projectId = "vortex-selfhelp",
            applicationId = "1:103897336562:android:7c5100e9950638bb5ede6b",
            apiKey = "AIzaSyAqWEXaTkmv-4MPTJogNbEPiuqoY4pgXrc"
        )
    )
    GlobalScope.launch {
        Firebase.remoteConfig.fetch(minimumFetchInterval = 30.minutes)
        Firebase.remoteConfig.activate()
    }
}