package com.coding.va.selfhelp.presentation.screens.craft

import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.ExperimentalLayoutApi
import androidx.compose.foundation.layout.FlowRow
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.width
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.Surface
import androidx.compose.material.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.domain.model.ImbueOption
import com.coding.va.selfhelp.domain.model.getEnergy
import com.coding.va.selfhelp.presentation.commoninterface.toIntOrZero
import com.coding.va.selfhelp.presentation.components.Button
import com.coding.va.selfhelp.presentation.components.OutlinedTextField
import com.coding.va.selfhelp.presentation.components.errorbox.ErrorBox
import com.coding.va.selfhelp.presentation.components.moveFocusOnTab
import com.coding.va.selfhelp.presentation.components.onlyDesktop
import com.coding.va.selfhelp.presentation.components.plinfield.PlinTextField
import com.coding.va.selfhelp.presentation.components.selectablefield.SelectableField
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldContent
import com.coding.va.selfhelp.presentation.screens.imbue.ImbueTypes
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueEnergySupplier
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueEvent
import com.coding.va.selfhelp.presentation.screens.imbue.model.isEnergyAmountValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.isImbueOptionValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.isPlinValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.isResourceAmountValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.isResourceTypeValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.isSpellSkillValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.isTargetValid
import com.coding.va.selfhelp.presentation.screens.verify.VerifySheet
import com.coding.va.selfhelp.theme.VortexTypography

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun ImbueContent(
    display: ImbueDisplay,
    onEvent: ((ImbueEvent) -> Unit)? = null
) {
    val numberRegex = remember { Regex("^\\d+\$") }
    val typography = VortexTypography()

    Surface(modifier = Modifier.fillMaxSize().background(Color.White)) {
        display.errorBox?.let {
            ErrorBox(
                display = it,
                onConfirmation = { },
                onDismissRequest = { onEvent?.invoke(ImbueEvent.DismissError) })
        }

        display.verifySheet?.let {
            VerifySheet(
                display = it,
                onConfirm = { onEvent?.invoke(ImbueEvent.AddImbue) },
                onDismiss = { onEvent?.invoke(ImbueEvent.DismissError) }
            )
        }

        Column(modifier = Modifier.padding(24.dp)) {
            Text(text = display.title, style = typography.headlineLarge)
            Text(text = display.description, style = typography.titleLarge)

            Column(modifier = Modifier.padding(top = 24.dp)) {
                if (display.isPerson) {
                    PlinTextField(
                        display.imbueTarget,
                        isError = display.shouldValidate && !display.form.isTargetValid(),
                        value = display.form.targetPlin ?: Pair("", ""),
                        plinWidth = 150.dp,
                        onValueChange = {
                            onEvent?.invoke(
                                ImbueEvent.UpdateImbueForm(
                                    display.form.copy(
                                        targetPlin = it
                                    )
                                )
                            )
                        },
                    )
                } else {
                    OutlinedTextField(
                        modifier = Modifier.moveFocusOnTab(),
                        isError = display.shouldValidate && !display.form.isTargetValid(),
                        value = display.form.targetItin.orEmpty(),
                        placeholder = { Text(text = display.imbueTarget.plinHint) },
                        onValueChange = {
                            onEvent?.invoke(
                                ImbueEvent.UpdateImbueForm(
                                    display.form.copy(
                                        targetItin = it
                                    )
                                )
                            )
                        },
                        label = { Text(text = display.imbueTarget.plinLabel) }
                    )
                }

                OutlinedTextField(
                    modifier = Modifier.height(100.dp).width(350.dp).moveFocusOnTab(),
                    value = display.form.notes,
                    placeholder = { Text(text = display.imbueNotes.hint) },
                    onValueChange = {
                        onEvent?.invoke(
                            ImbueEvent.UpdateImbueForm(
                                display.form.copy(
                                    notes = it
                                )
                            )
                        )
                    },
                    label = { Text(text = display.imbueNotes.label) }
                )
                Text(
                    modifier = Modifier.padding(top = 16.dp, bottom = 16.dp),
                    text = display.imbueDescription,
                    style = typography.bodyMedium
                )
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    display.form.imbueResources.forEach { entry ->
                        FlowRow(verticalArrangement = Arrangement.Bottom) {
                            Column(
                                modifier = Modifier.border(3.dp, Color.Black, RoundedCornerShape(8.dp))
                                    .padding(top = 16.dp, start = 16.dp, end = 16.dp, bottom = 20.dp),
                            ) {
                                Text(
                                    modifier = Modifier.padding(top = 16.dp, bottom = 16.dp),
                                    text = display.imbueEffectNumber + entry.key,
                                    style = typography.bodyMedium
                                )
                                FlowRow() {

                                    SelectableField(
                                        modifier = Modifier.width(200.dp).padding(start = 8.dp)
                                            .moveFocusOnTab(),
                                        isError = display.shouldValidate && !entry.value.isResourceTypeValid(),
                                        display = display.imbueResource.imbueType,
                                        value = entry.value.imbueType?.displayName,
                                        onSelected = { result ->
                                            onEvent?.invoke(
                                                ImbueEvent.UpdateImbueForm(
                                                    display.form.copy(
                                                        imbueResources = display.form.imbueResources.toMutableMap()
                                                            .apply {
                                                                val resource =
                                                                    ImbueTypes.getAllImbueTypes(display.isPerson)
                                                                        .firstOrNull { it.id == result.id }
                                                                this[entry.key] =
                                                                    entry.value.copy(
                                                                        imbueType = resource,
                                                                        imbueOption = null,
                                                                        amount = if (resource?.multiplePossible == false) "1" else this[entry.key]?.amount.orEmpty(),
                                                                        skillSpell = if (resource?.hasOpenPowerField == true) {
                                                                            entry.value.skillSpell
                                                                        } else ""
                                                                    )
                                                            }
                                                    )
                                                )
                                            )
                                        }
                                    )
                                    if (entry.value.imbueType?.options?.isEmpty() != true) {
                                        SelectableField(
                                            modifier = Modifier.width(200.dp).padding(start = 8.dp)
                                                .moveFocusOnTab(),
                                            isError = display.shouldValidate && !entry.value.isImbueOptionValid(),
                                            display = display.imbueResource.imbueOption.copy(content = entry.value.imbueType?.options?.map {
                                                SelectableFieldContent(displayValue = it.displayName, id = it.name)
                                            }.orEmpty()),
                                            value = entry.value.imbueOption?.displayName,
                                            onSelected = { result ->
                                                onEvent?.invoke(
                                                    ImbueEvent.UpdateImbueForm(
                                                        display.form.copy(
                                                            imbueResources = display.form.imbueResources.toMutableMap()
                                                                .apply {
                                                                    val option = ImbueOption.valueOf(result.id)
                                                                    this[entry.key] = entry.value.copy(
                                                                        imbueOption = option,
                                                                        energyAmount = option?.let { (option.getEnergy(entry.value.imbueType) * entry.value.amount.toIntOrZero()).toString() }
                                                                            .orEmpty()
                                                                    )
                                                                }
                                                        )
                                                    )
                                                )
                                            }
                                        )
                                    }

                                    OutlinedTextField(
                                        modifier = Modifier.width(150.dp).padding(start = 8.dp)
                                            .moveFocusOnTab(),
                                        isError = display.shouldValidate && !entry.value.isResourceAmountValid(),
                                        value = display.form.imbueResources[entry.key]?.amount.orEmpty(),
                                        enabled = entry.value.imbueType?.multiplePossible ?: true,
                                        placeholder = { Text(text = display.imbueResource.amount.hint) },
                                        onValueChange = { result ->
                                            if (result.isEmpty() || result.matches(numberRegex)) {
                                                onEvent?.invoke(
                                                    ImbueEvent.UpdateImbueForm(
                                                        display.form.copy(
                                                            imbueResources = display.form.imbueResources.toMutableMap()
                                                                .apply {
                                                                    val option = entry.value.imbueOption
                                                                    this[entry.key] = entry.value.copy(
                                                                        amount = result,
                                                                        energyAmount = option?.let { (option.getEnergy(entry.value.imbueType) * result.toIntOrZero()).toString() }
                                                                            .orEmpty()
                                                                    )
                                                                }
                                                        )
                                                    )
                                                )
                                            }
                                        },
                                        label = { Text(text = display.imbueResource.amount.label) }
                                    )

                                    if (entry.value.imbueType?.hasOpenPowerField == true) {
                                        val isCustom = entry.value.imbueType?.id == ImbueTypes.CUSTOM
                                        val fieldDisplay = if (isCustom) {
                                            display.imbueResource.custom
                                        } else {
                                            display.imbueResource.skillSpell
                                        }
                                        OutlinedTextField(
                                            modifier = Modifier
                                                .width(if (isCustom) 400.dp else 250.dp)
                                                .padding(start = 8.dp)
                                                .moveFocusOnTab(),
                                            isError = display.shouldValidate && !entry.value.isSpellSkillValid(),
                                            value = entry.value.skillSpell,
                                            placeholder = { Text(text = fieldDisplay.hint) },
                                            onValueChange = {
                                                onEvent?.invoke(
                                                    ImbueEvent.UpdateImbueForm(
                                                        display.form.copy(
                                                            imbueResources = display.form.imbueResources.toMutableMap()
                                                                .apply {
                                                                    this[entry.key] = entry.value.copy(
                                                                        skillSpell = it
                                                                    )
                                                                }
                                                        )
                                                    )
                                                )
                                            },
                                            label = { Text(text = fieldDisplay.label) }
                                        )
                                    }

                                    OutlinedTextField(
                                        modifier = Modifier.width(150.dp).padding(start = 8.dp)
                                            .moveFocusOnTab(),
                                        value = entry.value.energyAmount,
                                        enabled = entry.value.imbueType?.canModifyEnergy ?: display.imbueResource.energyAmount.enabled,
                                        placeholder = { Text(text = display.imbueResource.energyAmount.hint) },
                                        onValueChange = {
                                            onEvent?.invoke(
                                                ImbueEvent.UpdateImbueForm(
                                                    display.form.copy(
                                                        imbueResources = display.form.imbueResources.toMutableMap()
                                                            .apply {
                                                                this[entry.key] = entry.value.copy(
                                                                    energyAmount = it
                                                                )
                                                            }
                                                    )
                                                )
                                            )
                                        },
                                        label = { Text(text = display.imbueResource.energyAmount.label) }
                                    )

                                    SelectableField(
                                        modifier = Modifier.width(200.dp).padding(start = 8.dp)
                                            .moveFocusOnTab(),
                                        display = display.imbueResource.energyType,
                                        value = entry.value.energyType.displayName,
                                        onSelected = {
                                            onEvent?.invoke(
                                                ImbueEvent.UpdateImbueForm(
                                                    display.form.copy(
                                                        imbueResources = display.form.imbueResources.toMutableMap()
                                                            .apply {
                                                                this[entry.key] = entry.value.copy(
                                                                    energyType = EnergyType.valueOf(it.id)
                                                                )
                                                            }
                                                    )
                                                )
                                            )
                                        }
                                    )

                                    PlinTextField(
                                        modifier = Modifier.padding(start = 8.dp),
                                        display = display.imbueResource.plin,
                                        isError = display.shouldValidate && !entry.value.isPlinValid(),
                                        value = entry.value.headImbuerPlin,
                                        onValueChange = {
                                            onEvent?.invoke(
                                                ImbueEvent.UpdateImbueForm(
                                                    display.form.copy(
                                                        imbueResources = display.form.imbueResources.toMutableMap()
                                                            .apply {
                                                                this[entry.key] = entry.value.copy(
                                                                    headImbuerPlin = it,
                                                                    energySuppliers = entry.value.energySuppliers.toMutableMap()
                                                                        .apply {
                                                                            this[1] = this[1]?.copy(plin = it) ?: ImbueEnergySupplier()
                                                                        }
                                                                )
                                                            }
                                                    )
                                                )
                                            )
                                        },
                                    )
                                }
                                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                                    Text(
                                        modifier = Modifier.padding(top = 16.dp),
                                        text = display.imbueResource.energySupplierDescription + entry.value.energyType.displayName,
                                        style = typography.bodyMedium
                                    )
                                    Text(
                                        modifier = Modifier.padding(bottom = 16.dp),
                                        text = "Current energy: " + entry.value.energySuppliers.values.mapNotNull { it.amount.toIntOrNull() }.sum(),
                                        style = typography.bodyMedium
                                    )
                                    entry.value.energySuppliers.forEach { supplier ->
                                        Row(verticalAlignment = Alignment.Bottom) {
                                            FlowRow(
                                                modifier = Modifier.border(3.dp, Color.Gray, RoundedCornerShape(8.dp))
                                                    .padding(top = 16.dp, start = 16.dp, end = 16.dp, bottom = 20.dp),
                                            ) {
                                                OutlinedTextField(
                                                    modifier = Modifier.width(150.dp).padding(start = 8.dp)
                                                        .moveFocusOnTab(),
                                                    isError = display.shouldValidate && !entry.value.isEnergyAmountValid(),
                                                    value = supplier.value.amount,
                                                    enabled = display.imbueResource.energySupplierAmount.enabled,
                                                    placeholder = { Text(text = display.imbueResource.energySupplierAmount.hint) },
                                                    onValueChange = {
                                                        onEvent?.invoke(
                                                            ImbueEvent.UpdateImbueForm(
                                                                display.form.copy(
                                                                    imbueResources = display.form.imbueResources.toMutableMap()
                                                                        .apply {
                                                                            this[entry.key] = entry.value.copy(
                                                                                energySuppliers = entry.value.energySuppliers.toMutableMap()
                                                                                    .apply {
                                                                                        this[supplier.key] =
                                                                                            supplier.value.copy(
                                                                                                amount = it
                                                                                            )
                                                                                    }
                                                                            )
                                                                        }
                                                                )
                                                            )
                                                        )
                                                    },
                                                    label = { Text(text = display.imbueResource.energySupplierAmount.label) }
                                                )

                                                PlinTextField(
                                                    display = display.imbueResource.energySupplierPlin,
                                                    modifier = Modifier.padding(start = 8.dp)
                                                        .moveFocusOnTab(),
                                                    isError = display.shouldValidate && !supplier.value.plin.first.isNotBlank(),
                                                    value = supplier.value.plin,
                                                    onValueChange = {
                                                        onEvent?.invoke(
                                                            ImbueEvent.UpdateImbueForm(
                                                                display.form.copy(
                                                                    imbueResources = display.form.imbueResources.toMutableMap()
                                                                        .apply {
                                                                            this[entry.key] = entry.value.copy(
                                                                                energySuppliers = entry.value.energySuppliers.toMutableMap()
                                                                                    .apply {
                                                                                        this[supplier.key] =
                                                                                            supplier.value.copy(
                                                                                                plin = it
                                                                                            )
                                                                                    }
                                                                            )
                                                                        }
                                                                )
                                                            )
                                                        )
                                                    },
                                                )
                                            }
                                            if (entry.value.energySuppliers.size == supplier.key) {
                                                FlowRow {
                                                    if (supplier.key > 1) {
                                                        Button(
                                                            modifier = Modifier.padding(top = 10.dp, start = 12.dp).height(50.dp).width(50.dp),
                                                            onClick = {
                                                                onEvent?.invoke(
                                                                    ImbueEvent.RemovePowerSupplier(entry.key, supplier.key)
                                                                )
                                                            }) {
                                                            Text(text = "-")
                                                        }
                                                    }
                                                    Button(
                                                        modifier = Modifier.padding(top = 10.dp, start = 12.dp).height(50.dp).width(50.dp),
                                                        onClick = {
                                                            onEvent?.invoke(
                                                                ImbueEvent.AddPowerSupplier(entry.key)
                                                            )
                                                        }) {
                                                        Text(text = "+")
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            if (display.form.imbueResources.size == entry.key) {
                                if (entry.key > 1) {
                                    Button(
                                        modifier = Modifier.padding(top = 10.dp, start = 12.dp)
                                            .height(50.dp)
                                            .width(50.dp),
                                        onClick = { onEvent?.invoke(ImbueEvent.RemoveImbueResource(entry.key)) }) {
                                        Text(text = "-")
                                    }
                                }
                                Button(
                                    modifier = Modifier.padding(top = 10.dp, start = 12.dp)
                                        .height(50.dp)
                                        .width(50.dp),
                                    onClick = { onEvent?.invoke(ImbueEvent.AddImbueResource) }) {
                                    Text(text = "+")
                                }
                            }
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.weight(1f))
            Row(modifier = Modifier.padding(top = 24.dp)) {
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(ImbueEvent.Back) }) {
                    Text(text = "Back to Home")
                }
                Spacer(modifier = Modifier.weight(1f))
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(ImbueEvent.Verify) }) {
                    Text(text = display.validate)
                }
            }
        }
    }
}


