package com.coding.va.selfhelp.presentation.screens.success.model

import androidx.compose.ui.text.AnnotatedString
import com.coding.va.selfhelp.presentation.screens.model.VortexItemCardDisplay

sealed class SuccessDisplay() {

    data class Data(
        val title: String,
        val description: AnnotatedString,
        val extraInfo: AnnotatedString,
        val doneButton: String,
        val vortexPrintingCard: VortexItemCardDisplay?
    ) : SuccessDisplay()

    data class Loading(
        val display: Data,
    ) : SuccessDisplay()

    data class Failure(
        val title: String,
        val description: String,
        val retryButton: String,
    ) : SuccessDisplay()
}


