import com.coding.va.selfhelp.domain.model.ImbueOption
import com.coding.va.selfhelp.domain.model.ImbueType
import com.coding.va.selfhelp.presentation.commoninterface.toIntOrZero
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.plinToText
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.methods.LoadingButtonDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.craft.model.toVerifySheet
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay
import com.coding.va.selfhelp.presentation.screens.model.VortexItemCardDisplay
