data class RechargeDisplay(
    val title: String,
    val description: String,
    val rechargeDescription: String,
    val rechargeTarget: FieldDisplay,
    val rechargeNotes: FieldDisplay,
    val rechargeResource: RechargeResourceDisplay,
    val form: RechargeForm,
    val shouldValidate: Boolean,
    val errorBox: ErrorBoxDisplay?,
    val verifySheet: VerifySheetDisplay?,
)

data class RechargeResourceDisplay(
    val energyAmount: FieldDisplay,
    val energyType: SelectableFieldDisplay,
    val plin: PlinFieldDisplay,
    val energySupplierPlin: PlinFieldDisplay,
    val energySupplierAmount: FieldDisplay,
    val energySupplierDescription: String,
)

data class RechargeForm(
    val targetItin: String,
    val notes: String,
    val rechargeResources: Map<Int, RechargeResourceForm>
)

data class RechargeResourceForm(
    val energyAmount: String = "",
    val energyType: EnergyType = EnergyType.SPIRITUAL_MANA,
    val headRechargerPlin: Pair<String, String> = Pair("", ""),
    val energySuppliers: Map<Int, RechargeEnergySupplier> = mapOf(1 to RechargeEnergySupplier()),
)

data class RechargeEnergySupplier(
    val amount: String = "",
    val plin: Pair<String, String> = Pair("", ""),
)

fun RechargeForm.isTargetValid(): Boolean = !targetItin.isNullOrBlank()

fun RechargeResourceForm.isEnergyAmountValid(): Boolean =
    energyAmount.toIntOrZero() == energySuppliers.values.sumOf { it.amount.toIntOrZero() }

fun RechargeResourceForm.isPlinValid(): Boolean = headRechargerPlin.first.isNotBlank() && headRechargerPlin.second.isNotBlank()

fun RechargeResourceForm.isValid(): Boolean {
    return isEnergyAmountValid() && isPlinValid()
}

fun Map<Int, RechargeResourceForm>.meetsMinRequirements(): Boolean {
    return this.values.all { it.isPlinValid() }
}

fun RechargeForm.isValid(): Boolean {
    return isTargetValid() && rechargeResources.all { it.value.isValid() }
}

fun RechargeForm.meetsMinRequirements(): Boolean {
    return isTargetValid() && rechargeResources.meetsMinRequirements()
}

fun RechargeForm.toResourcesText(): String {
    return rechargeResources.map { rs ->
        "Required energy: ${rs.value.energyAmount} ${rs.value.energyType.displayName} main recharger ${rs.value.headRechargerPlin.plinToText()}\nSupplied energy:\n" +
                rs.value.energySuppliers.map {
                    "       ${it.value.amount} ${rs.value.energyType.displayName} by ${it.value.plin.plinToText()}"
                }.joinToString(separator = "\n") + if (!rs.value.isEnergyAmountValid()) {
            " issue: Supplied Energy doesn't match the required energy"
        } else ""
    }.joinToString("\n\n")
}

fun RechargeForm.toVerifySheet(hasErrors: Boolean, isEnabled: Boolean): VerifySheetDisplay {
    return VerifySheetDisplay(
        title = if (hasErrors) "Something might be off" else "Time to verify your creation",
        description = if (hasErrors) "Some things don't add up. This might be because of valid reasons explained in the special notes. \nAre you sure the form is correct? Your recharge might fail if it's not." else "Everything looks good, but let's double check it",
        dismiss = "Back",
        confirm = LoadingButtonDisplay("Agree", false, isEnabled),
        resourcesLabel = "this is the recharge data we got from you",
        resources = this.toResourcesText() + "\n\nSpecial Notes:\n${notes}",
        lammyLabel = "preview of your recharge card",
        lammy = this.toVortexCard("---")
    )
}

fun RechargeForm.toVortexCard(imbueId: String): VortexItemCardDisplay {
    return VortexItemCardDisplay(
        header = "item recharge card",
        targetItin = targetItin,
        energyUsed = calculateTotalEnergyByType(this.rechargeResources),
        createdBy = rechargeResources.map { it.value.headRechargerPlin.plinToText() }.distinctBy { it }
            .joinToString("+"),
        imbueId = imbueId,
        power = "item has been recharged"
    )
}

fun calculateTotalEnergyByType(imbueResources: Map<Int, RechargeResourceForm>): Map<EnergyType, Int> {
    val result = mutableMapOf<EnergyType, Int>()

    fun processResource(resource: RechargeResourceForm) {
        // Add energyAmount for the current resource if present
        resource.energyType?.let { type ->
            resource.energyAmount?.let { amount ->
                result[type] = (result[type] ?: 0) + amount.toIntOrZero()
            }
        }
    }

    imbueResources.forEach { (_, resource) ->
        processResource(resource)
    }

    return result
}