package com.coding.va.selfhelp.presentation.methods

import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay

object ApiErrorDisplayProvider {

    fun error(error: String?) = ErrorBoxDisplay(
        title = "Something went wrong ):",
        description = "somehow we could not save your data, we got this error:\n$error",
        acceptButton = null,
        retryButton = "Ok"
    )
}