package com.coding.va.selfhelp.presentation.screens.craft

import com.coding.va.selfhelp.domain.model.CraftingResource
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldContent
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.CraftItemDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftForm
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftResourceDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftResourceForm
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay

object CraftItemDisplayProvider {

    fun provide() = CraftItemDisplay(
        title = "Craft an Item",
        description = "Please fill in the form below to start crafting your item",
        resourceDescription = "Please fill in the resources you're using to craft your item, put the resources and energy in an envelope and write the temporary ITIN code of your item on it (found on the next page), Please also write the PLIN of the crafter on the energy",
        itemTitle = FieldDisplay(
            label = "Item Name",
            hint = "What name should your item have?",
        ),
        itemDescription = FieldDisplay(
            label = "Item Description",
            hint = "What does the item look like",
        ),
        itemNotes = FieldDisplay(
            label = "Special Notes",
            hint = "Anything else we need to know to process your creation, special items used etc"
        ),
        itemImbueCap = FieldDisplay(label = "Imbue Cap", hint = "how high is the imbue cap you want?"),
        itemCraftResource = provideEmptyCraftResource(),
        form = ItemCraftForm(
            name = "",
            description = "",
            imbueCap = "",
            notes = "",
            resources = mutableMapOf(1 to ItemCraftResourceForm())
        ),
        shouldValidate = false,
        errorBox = null,
        verifySheet = null,
    )

    fun provideEmptyCraftResource() = ItemCraftResourceDisplay(
        resourceAmount = FieldDisplay(label = "Amount", hint = " how many of this resource"),
        resourceType = SelectableFieldDisplay(
            label = "Select Resource",
            content = CraftingResource.entries.map {
                SelectableFieldContent(
                    it.resourceName,
                    it.name
                )
            }
        ),
        energyAmount = FieldDisplay(
            label = "Energy",
            hint = "how much mana / inspiration etc",
        ),
        energyType = SelectableFieldDisplay(
            label = "Select Energy Type",
            content = EnergyType.entries.map {
                SelectableFieldContent(
                    it.displayName,
                    it.name
                )
            }
        ),
        plin = PlinFieldDisplay(
            plinLabel = "PLIN",
            plinHint = "PLIN of the crafter that used this resource",
            chinLabel = "CHIN",
            chinHint = "CHIN"
        ),
    )

    fun reguiredError() = ErrorBoxDisplay(
        title = "This is not right",
        description = "please finish filling in the form first",
        acceptButton = null,
        retryButton = "Alright, let me do that"
    )
}