package com.coding.va.selfhelp.presentation.screens.imbue

import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.lifecycle.compose.LocalLifecycleOwner
import com.coding.va.selfhelp.presentation.commoninterface.onCreate
import com.coding.va.selfhelp.presentation.screens.craft.ImbueContent
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions

@Composable
fun ImbueScreen(
    viewModel: ImbueViewModel,
    mainActions: MainActions,
    isPerson: Boolean,
) {
    val display by viewModel.display.collectAsState()

    LocalLifecycleOwner.current.onCreate(display) {
        viewModel.initVM(mainActions, isPerson)
    }

    ImbueContent(display, viewModel::onEvent)
}