package com.coding.va.selfhelp.presentation.screens.craft.navigation

import androidx.navigation.NavGraphBuilder
import androidx.navigation.compose.composable
import com.coding.va.selfhelp.presentation.methods.GenericNavType
import com.coding.va.selfhelp.presentation.screens.craft.CraftItemScreen
import com.coding.va.selfhelp.presentation.screens.landing.LandingScreen
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import org.koin.compose.koinInject
import kotlin.reflect.typeOf

fun NavGraphBuilder.CraftItemRoute(actions: MainActions) {
    composable<MainDestinations.CraftItem>(
        typeMap = mapOf(
            typeOf<MainDestinations.CraftItem>() to GenericNavType(MainDestinations.Success.serializer()),
        )
    ) {
        CraftItemScreen(koinInject(), actions)
    }
}
