package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.model.SheetEntryData
import com.coding.va.selfhelp.domain.respository.SheetsRepository
import com.coding.va.selfhelp.presentation.screens.recharge.model.RechargeForm
import org.koin.core.component.KoinComponent


class AddRecharge(private val repository: SheetsRepository) : KoinComponent {

    suspend operator fun invoke(form: RechargeForm): Result<SheetEntryData> {
        return repository.addRecharge(form)
    }
}