import com.coding.va.selfhelp.domain.model.ImbueOption
import com.coding.va.selfhelp.domain.model.ImbueType
import com.coding.va.selfhelp.presentation.commoninterface.toIntOrZero
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.plinToText
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.methods.LoadingButtonDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.ImbueTypes
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay
import com.coding.va.selfhelp.presentation.screens.model.VortexItemCardDisplay
import com.coding.va.selfhelp.presentation.screens.verify.model.VerifySheetDisplay

data class ImbueDisplay(
    val title: String,
    val description: String,
    val imbueDescription: String,
    val imbueEffectNumber: String,
    val imbueTarget: PlinFieldDisplay,
    val isPerson: Boolean,
    val imbueNotes: FieldDisplay,
    val imbueResource: ImbueResourceDisplay,
    val form: ImbueForm,
    val shouldValidate: Boolean,
    val errorBox: ErrorBoxDisplay?,
    val verifySheet: VerifySheetDisplay?,
    val validate: String,
)

data class ImbueResourceDisplay(
    val amount: FieldDisplay,
    val imbueType: SelectableFieldDisplay,
    val imbueOption: SelectableFieldDisplay,
    val energyAmount: FieldDisplay,
    val energyType: SelectableFieldDisplay,
    val skillSpell: FieldDisplay,
    val custom: FieldDisplay,
    val plin: PlinFieldDisplay,
    val energySupplierPlin: PlinFieldDisplay,
    val energySupplierAmount: FieldDisplay,
    val energySupplierDescription: String,
)

data class ImbueForm(
    val isPerson: Boolean,
    val targetItin: String?,
    val targetPlin: Pair<String, String>?,
    val notes: String,
    val imbueResources: Map<Int, ImbueResourceForm>
)

data class ImbueResourceForm(
    val amount: String = "1",
    val imbueType: ImbueType? = null,
    val imbueOption: ImbueOption? = null,
    val skillSpell: String = "",
    val energyAmount: String = "",
    val energyType: EnergyType = EnergyType.SPIRITUAL_MANA,
    val headImbuerPlin: Pair<String, String> = Pair("", ""),
    val energySuppliers: Map<Int, ImbueEnergySupplier> = mapOf(1 to ImbueEnergySupplier()),
)

data class ImbueEnergySupplier(
    val amount: String = "",
    val plin: Pair<String, String> = Pair("", ""),
)

fun ImbueResourceForm.getPower(): String? =
    imbueType?.powerText?.replace("[AMOUNT]", amount)
        ?.replace("[VALUE]", imbueOption?.displayName.orEmpty()) + " $skillSpell"

fun ImbueForm.isTargetValid(): Boolean = (!targetPlin?.first.isNullOrBlank() && !targetPlin?.second.isNullOrBlank()) || !targetItin.isNullOrBlank()

fun ImbueResourceForm.isResourceAmountValid(): Boolean =
    amount.isNotBlank() && amount.toIntOrZero() > 0

fun ImbueResourceForm.isEnergyAmountValid(): Boolean =
    energyAmount.toIntOrZero() == energySuppliers.values.sumOf { it.amount.toIntOrZero() }

fun ImbueResourceForm.isPlinValid(): Boolean = headImbuerPlin.first.isNotBlank() && headImbuerPlin.second.isNotBlank()

fun ImbueResourceForm.isResourceTypeValid(): Boolean = imbueType != null

fun ImbueResourceForm.isImbueOptionValid(): Boolean = if (imbueType?.id == ImbueTypes.CUSTOM) true else imbueOption != null

fun ImbueResourceForm.isSpellSkillValid(): Boolean = if (imbueType?.hasOpenPowerField == true) {
    skillSpell.isNotBlank()
} else true

fun ImbueResourceForm.isValid(): Boolean {
    return isResourceAmountValid() && isEnergyAmountValid() && isPlinValid() && isResourceTypeValid() && isImbueOptionValid() && isSpellSkillValid()
}

fun Map<Int, ImbueResourceForm>.meetsMinRequirements(): Boolean {
    return this.values.all { it.isPlinValid() && it.isResourceAmountValid() && it.isResourceTypeValid() && it.isSpellSkillValid() && it.isImbueOptionValid() }
}

fun ImbueForm.isValid(): Boolean {
    return isTargetValid() && imbueResources.all { it.value.isValid() }
}

fun ImbueForm.meetsMinRequirements(): Boolean {
    return isTargetValid() && imbueResources.meetsMinRequirements()
}

fun ImbueForm.toResourcesText(): String {
    return imbueResources.map { rs ->
        "${rs.value.amount}x ${rs.value.imbueType?.displayName}     ${rs.value.imbueOption?.displayName.orEmpty()}      ${rs.value.skillSpell} by ${rs.value.headImbuerPlin.plinToText()}\nRequired energy: ${rs.value.energyAmount} ${rs.value.energyType.displayName}\nSupplied energy:\n" +
                rs.value.energySuppliers.map {
                    "       ${it.value.amount} ${rs.value.energyType.displayName} by ${it.value.plin.plinToText()}"
                }.joinToString(separator = "\n") + if (!rs.value.isEnergyAmountValid()) {
            " issue: Supplied Energy doesn't match the required energy"
        } else ""
    }.joinToString("\n\n")
}

fun ImbueForm.toVerifySheet(hasErrors: Boolean, isEnabled: Boolean): VerifySheetDisplay {
    return VerifySheetDisplay(
        title = if (hasErrors) "Something might be off" else "Time to verify your creation",
        description = if (hasErrors) "Some things don't add up. This might be because of valid reasons explained in the special notes. \nAre you sure the form is correct? Your creation might be declined if it's not." else "Everything looks good, but let's double check it",
        dismiss = "Back",
        confirm = LoadingButtonDisplay("Agree", false, isEnabled),
        resourcesLabel = "this is the imbue data we got from you",
        resources = this.toResourcesText() + "\n\nSpecial Notes:\n${notes}",
        lammyLabel = "preview of your imbue card",
        lammy = this.toVortexCard("---")
    )
}

fun ImbueForm.toVortexCard(imbueId: String): VortexItemCardDisplay {
    return VortexItemCardDisplay(
        header = if (!isPerson) {
            "temporary item imbue card"
        } else "temporary person imbue card",
        targetItin = targetItin,
        targetPlin = targetPlin?.plinToText(),
        energyUsed = calculateTotalEnergyByType(this.imbueResources),
        createdBy = imbueResources.map { it.value.headImbuerPlin.plinToText() }.distinctBy { it }
            .joinToString("+"),
        imbueId = imbueId,
        power = imbueResources.entries.map { it.value.getPower() }.joinToString(separator = "\n"),
    )
}

fun calculateTotalEnergyByType(imbueResources: Map<Int, ImbueResourceForm>): Map<EnergyType, Int> {
    val result = mutableMapOf<EnergyType, Int>()

    fun processResource(resource: ImbueResourceForm) {
        // Add energyAmount for the current resource if present
        resource.energyType?.let { type ->
            resource.energyAmount?.let { amount ->
                result[type] = (result[type] ?: 0) + amount.toIntOrZero()
            }
        }
    }

    imbueResources.forEach { (_, resource) ->
        processResource(resource)
    }

    return result
}