@Composable
fun VortexItemCardUIFront(
    modifier: Modifier = Modifier,
    display: VortexItemCardDisplay,
) {
    Column(
        modifier = modifier
            .padding(vertical = 1.dp)
            .background(color = Color.White).padding(1.dp)
    ) {
        Column(
            modifier = Modifier
                .border(2.dp, Color.Black, RoundedCornerShape(8.dp))
                .padding(8.dp)
                .aspectRatio(1.75f)
        ) {
            Row {
                Spacer(modifier = Modifier.weight(1f))
                Text(text = display.header, fontSize = 12.sp, style = BodyBold)
                Spacer(modifier = Modifier.weight(1f))
            }
            Row(verticalAlignment = Alignment.CenterVertically) {
                Spacer(modifier = Modifier.weight(1f))
                display.tempItin?.let {
                    Column(horizontalAlignment = Alignment.End) {
                        Text(text = "Temp ITIN", fontSize = 14.sp, style = BodyBold)
                        Text(text = display.tempItin, fontSize = 21.sp, style = BodyBold)
                    }
                }
                display.imbueId?.let {
                    Column(horizontalAlignment = Alignment.End) {
                        Text(text = "imbue ID", fontSize = 14.sp, style = BodyBold)
                        Text(text = display.imbueId, fontSize = 21.sp, style = BodyBold)
                    }
                }
                Image(
                    modifier = Modifier.size(49.dp),
                    painter = painterResource(Res.drawable.vortex_logo),
                    contentDescription = "content description"
                )
            }
            Column(modifier = Modifier.offset(y = (-12).dp)) {
                display.itemName?.let {
                    Row {
                        Text(
                            modifier = Modifier.width(120.dp),
                            text = "name:", fontSize = 14.sp, style = BodyBold
                        )
                        Text(text = display.itemName, fontSize = 14.sp, style = BodyBold)
                    }
                }

                display.itemDescription?.let {
                    Row(modifier = Modifier.padding(top = 12.dp)) {
                        Text(
                            modifier = Modifier.width(120.dp),
                            text = "description:",
                            fontSize = 14.sp, style = BodyBold
                        )
                        Text(text = display.itemDescription, fontSize = 14.sp, style = BodyBold)
                    }
                }
                display.targetItin?.let {
                    if (it.isNotBlank()) {
                        Row(modifier = Modifier.padding(top = 6.dp)) {
                            Text(
                                modifier = Modifier,
                                text = "Itin:",
                                fontSize = 14.sp, style = BodyBold
                            )
                            Text(text = display.targetItin, fontSize = 14.sp, style = BodyBold)
                        }
                    }
                }

                display.targetPlin?.let {
                    if (it.isNotBlank()) {
                        Row(modifier = Modifier.padding(top = 6.dp)) {
                            Text(
                                modifier = Modifier.width(120.dp),
                                text = "Plin:",
                                fontSize = 14.sp, style = BodyBold
                            )
                            Text(text = display.targetPlin, fontSize = 14.sp, style = BodyBold)
                        }
                    }
                }

                display.energyUsed?.let {
                    Column(modifier = Modifier.padding(start = 12.dp)) {
                        Text(
                            modifier = Modifier.padding(bottom = 4.dp, top = 6.dp),
                            text = "Energy Used",
                            fontSize = 12.sp, style = BodyBold
                        )
                        display.energyUsed.forEach { entry ->
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Text(
                                    modifier = Modifier.padding(end = 4.dp),
                                    text = entry.key.displayName,
                                    fontSize = 14.sp, style = BodyBold
                                )
                                Text(text = entry.value.toString(), fontSize = 14.sp, style = BodyBold)
                            }
                        }
                    }
                }

                Row(modifier = Modifier.padding(top = 12.dp)) {
                    Text(
                        modifier = Modifier.width(120.dp),
                        text = "Created by: ",
                        fontSize = 14.sp, style = BodyBold
                    )
                    Text(text = display.createdBy, fontSize = 14.sp, style = BodyBold)
                }
            }
        }
    }
}

@Composable
fun VortexItemCardUIBack(
    modifier: Modifier = Modifier,
    display: VortexItemCardDisplay,
) {

    Column(
        modifier = modifier
            .padding(vertical = 1.dp)
            .background(color = Color.White).padding(1.dp)
    ) {
        Column(
            modifier = Modifier
                .border(2.dp, Color.Black, RoundedCornerShape(8.dp))
                .padding(8.dp)
                .aspectRatio(1.75f)
        ) {
            Row {
                Spacer(modifier = Modifier.weight(1f))
                Text(text = "Description", fontSize = 12.sp, style = BodyBold)
                Spacer(modifier = Modifier.weight(1f))
            }
            Row() {
                Image(
                    modifier = Modifier.size(49.dp),
                    painter = painterResource(Res.drawable.vortex_logo),
                    contentDescription = "content description"
                )
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(end = 8.dp, bottom = 8.dp)
                        .border(2.dp, Color.Black, RoundedCornerShape(8.dp))
                        .padding(8.dp)
                        .aspectRatio(1.75f)
                ) {
                    display.imbueCap?.let {
                        Text(
                            text = "Imbuecap: ${display.imbueCap}",
                            fontSize = 14.sp,
                            style = BodyBold
                        )
                    }
                    display.power?.let {
                        Text(text = it, fontSize = 14.sp, style = BodyBold)
                    }
                }
            }
        }
    }
}