import com.coding.va.selfhelp.domain.model.ImbueOption
import com.coding.va.selfhelp.domain.model.ImbueType

object ImbueTypes {

    const val CUSTOM = "CUSTOM"

    fun extraEnergy() = ImbueType(
        id = "ENERGY",
        displayName = "Extra Energy",
        options = listOf(
            ImbueOption.ENERGY_1,
            ImbueOption.ENERGY_2,
            ImbueOption.ENERGY_3,
            ImbueOption.ENERGY_4,
            ImbueOption.ENERGY_5,
            ImbueOption.ENERGY_6,
        ),
        multiplePossible = true,
        isUpgraded = false,
        powerText = "[AMOUNT] Extra [VALUE] per day"
    )

    fun spells() = ImbueType(
        id = "SPELLS",
        displayName = "Engrave Spell",
        options = listOf(
            ImbueOption.SPELL_1,
            ImbueOption.SPELL_2,
            ImbueOption.SPELL_3,
        ),
        multiplePossible = true,
        isUpgraded = false,
        powerText = "[AMOUNT]x per day [VALUE]",
        hasOpenPowerField = true
    )

    fun resistances() = ImbueType(
        id = "RESISTANCE",
        displayName = "Engrave Resistance",
        options = listOf(
            ImbueOption.RESISTANCE_CONFUSE,
