            ImbueOption.RESISTANCE_HARDEN,
            ImbueOption.RESISTANCE_MOVEMENT,
            ImbueOption.RESISTANCE_BREAK_ENCHANTMENT,
            ImbueOption.RESISTANCE_BREAK_ALL_ENCHANTMENT,
        ),
        multiplePossible = true,
        isUpgraded = false,
        powerText = "[AMOUNT]x per day resist [VALUE]",
    )

    fun immunities() = ImbueType(
        id = "IMMUNITIES",
        displayName = "Engrave Permanent Resistance",
        options = listOf(
            ImbueOption.RESISTANCE_CONFUSE,
            ImbueOption.RESISTANCE_FASCINATE,
            ImbueOption.RESISTANCE_FEAR,
            ImbueOption.RESISTANCE_INCITE_AGGRESSION,
            ImbueOption.RESISTANCE_MUTE,
            ImbueOption.RESISTANCE_SLOW,
            ImbueOption.RESISTANCE_COMMAND,
            ImbueOption.RESISTANCE_CURSE_LIFE,
            ImbueOption.RESISTANCE_FREEZE,
            ImbueOption.RESISTANCE_SHATTER,
            ImbueOption.RESISTANCE_SLEEP,
            ImbueOption.RESISTANCE_STRIKE,
            ImbueOption.RESISTANCE_POISON,
            ImbueOption.RESISTANCE_DISEASE,
            ImbueOption.RESISTANCE_FORCE_TRUTH,
            ImbueOption.RESISTANCE_PARALYZE,
            ImbueOption.RESISTANCE_TORTURE,
