    fun protection() = ImbueType(
        id = "PROTECTION",
        displayName = "Engrave Protection",
        options = listOf(
            ImbueOption.ARMOR,
            ImbueOption.ARMOR_2,
            ImbueOption.ARMOR_3,
            ImbueOption.HEALTH,
