    fun teacher() = ImbueType(
        id = "TEACHER",
        displayName = "Inspiration of the Teacher",
        options = listOf(
            ImbueOption.TEACHER,
        ),
        multiplePossible = true,
        isUpgraded = false,
        powerText = "[AMOUNT]x extra teaching slots"
    )

    fun custom() = ImbueType(
        id = CUSTOM,
        displayName = "Custom Imbue (Existing)",
        options = emptyList(),
        multiplePossible = true,
        isUpgraded = false,
        hasOpenPowerField = true,
        canModifyEnergy = true,
        powerText = "[AMOUNT]x Custom Imbue [VALUE]",
    )

    fun getAllImbueTypes(isPerson: Boolean): List<ImbueType> {
        return listOf(
            extraEnergy(),
            spells(),
            resistances(),
            immunities(),
            protection(),
            skill(),
            weaponSkill(),
            reduceDamage(),
            reduceDamagePermanent(),
            teacher(),
            custom(),
        ).filter {
            if (isPerson) {
                it.canBePersonal
            } else true
        }
    }
}