package com.coding.va.selfhelp.presentation.screens.craft.model

import com.coding.va.selfhelp.domain.model.CraftingResource
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.presentation.commoninterface.ceil
import com.coding.va.selfhelp.presentation.commoninterface.orZero
import com.coding.va.selfhelp.presentation.commoninterface.toIntOrZero
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.plinToText
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.methods.LoadingButtonDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueForm
import com.coding.va.selfhelp.presentation.screens.imbue.model.isEnergyAmountValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.toResourcesText
import com.coding.va.selfhelp.presentation.screens.imbue.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay
import com.coding.va.selfhelp.presentation.screens.model.VortexItemCardDisplay
import com.coding.va.selfhelp.presentation.screens.verify.model.VerifySheetDisplay

data class CraftItemDisplay(
    val title: String,
    val description: String,
    val resourceDescription: String,
    val itemTitle: FieldDisplay,
    val itemDescription: FieldDisplay,
    val itemNotes: FieldDisplay,
    val itemImbueCap: FieldDisplay,
    val itemCraftResource: ItemCraftResourceDisplay,
    val form: ItemCraftForm,
    val shouldValidate: Boolean,
    val errorBox: ErrorBoxDisplay?,
    val verifySheet: VerifySheetDisplay?,
)

data class ItemCraftResourceDisplay(
    val resourceAmount: FieldDisplay,
    val resourceType: SelectableFieldDisplay,
    val energyAmount: FieldDisplay,
    val energyType: SelectableFieldDisplay,
    val plin: PlinFieldDisplay,
)

data class ItemCraftForm(
    val name: String,
    val description: String,
    val imbueCap: String,
    val notes: String,
    val resources: Map<Int, ItemCraftResourceForm>
)

data class ItemCraftResourceForm(
    val resourceAmount: String = "",
    val resourceType: CraftingResource? = null,
    val energyAmount: String = "",
    val energyType: EnergyType = EnergyType.INSPIRATION,
    val plin: Pair<String, String> = Pair("", ""),
)

fun ItemCraftForm.toVortexCard(tempItin: String): VortexItemCardDisplay {
    return VortexItemCardDisplay(
        itemName = name,
        itemDescription = description,
        imbueCap = imbueCap,
        createdBy = resources.map { it.value.plin.plinToText() }.distinctBy { it }.joinToString("+"),
        tempItin = tempItin,
        power = null,
        header = "temporary item card",
    )
}

fun ItemCraftForm.getResourcesImbueCap(): Int =
    this.resources.map { it.value.resourceAmount.toIntOrZero() * it.value.resourceType?.imbueCap.orZero() }
        .sum()

fun ItemCraftForm.isTitleValid(): Boolean = name.isNotBlank()
fun ItemCraftForm.isDescriptionValid(): Boolean = description.isNotBlank()
fun ItemCraftForm.isImbueCapValid(): Boolean =
    imbueCap.toIntOrZero() > 0 && imbueCap.toIntOrZero() == getResourcesImbueCap()

fun ItemCraftResourceForm.isResourceAmountValid(): Boolean =
    resourceAmount.isNotBlank() && resourceAmount.toIntOrZero() > 0

fun ItemCraftResourceForm.isEnergyAmountValid(): Boolean =
    energyAmount.toIntOrZero() == (resourceAmount.toIntOrZero() * resourceType?.requiredEnergy.orZero()).ceil()
        .toInt()

fun ItemCraftResourceForm.isPlinValid(): Boolean = plin.first.isNotBlank() && plin.second.isNotBlank()
fun ItemCraftResourceForm.isResourceTypeValid(): Boolean = resourceType != null
fun ItemCraftResourceForm.isEnergyTypeValid(): Boolean = energyType != null

fun ItemCraftResourceForm.isValid(): Boolean {
    return isResourceAmountValid() && isEnergyAmountValid() && isPlinValid() && isResourceTypeValid() && isEnergyTypeValid()
}

fun Map<Int, ItemCraftResourceForm>.meetsMinRequirements(): Boolean {
    return this.values.any { it.isPlinValid() && it.isResourceTypeValid() && it.isResourceAmountValid() }
}

fun ItemCraftForm.isValid(): Boolean {
    return isTitleValid() && isDescriptionValid() && isImbueCapValid() && resources.all { it.value.isValid() }
}

fun ItemCraftForm.meetsMinRequirements(): Boolean {
    return isTitleValid() && isDescriptionValid() && resources.meetsMinRequirements()
}

fun ItemCraftForm.toResourcesText(): String {
    return resources.map {
        "${it.value.resourceAmount} ${it.value.resourceType?.resourceName} processed with ${it.value.energyAmount} ${it.value.energyType.displayName} by ${it.value.plin.plinToText()}" + if (!it.value.isEnergyAmountValid()) {
            " - Energy Amount is modified"
        } else ""
    }.joinToString(separator = "\n") + if (!isImbueCapValid()) {
        "\n\nIssue: Imbue Cap of ${this.imbueCap} differs from resources ${this.getResourcesImbueCap()}"
    } else ""
}

fun ItemCraftForm.toVerifySheet(hasErrors: Boolean, isEnabled: Boolean): VerifySheetDisplay {
    return VerifySheetDisplay(
        title = if (hasErrors) "Something might be off" else "Time to verify your creation",
        description = if (hasErrors) "Some things don't add up. This might be because of valid reasons explained in the special notes. \nAre you sure the form is correct? Your creation might be declined if it's not." else "Everything looks good, but let's double check it",
        dismiss = "Back",
        confirm = LoadingButtonDisplay("Agree", false, isEnabled),
        resourcesLabel = "these are the resources we got from you",
        resources = this.toResourcesText() + "\n\nSpecial Notes:\n${notes}",
        lammyLabel = "preview of your item card",
        lammy = this.toVortexCard("---")
    )
}

