import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.domain.use_cases.AddCraftedItem
import com.coding.va.selfhelp.domain.use_cases.AddImbue
import com.coding.va.selfhelp.domain.use_cases.CanMakeCreation
import com.coding.va.selfhelp.domain.use_cases.PrintingUseCase
import com.coding.va.selfhelp.presentation.methods.ApiErrorDisplayProvider
import com.coding.va.selfhelp.presentation.screens.craft.CraftItemDisplayProvider
import com.coding.va.selfhelp.presentation.screens.craft.model.CraftItemEvent
import com.coding.va.selfhelp.presentation.screens.craft.model.ItemCraftResourceForm
import com.coding.va.selfhelp.presentation.screens.craft.model.isValid
import com.coding.va.selfhelp.presentation.screens.craft.model.meetsMinRequirements
import com.coding.va.selfhelp.presentation.screens.craft.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueEnergySupplier
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueEvent
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueResourceForm
import com.coding.va.selfhelp.presentation.screens.imbue.model.isValid
import com.coding.va.selfhelp.presentation.screens.imbue.model.meetsMinRequirements
import com.coding.va.selfhelp.presentation.screens.imbue.model.toVerifySheet
import com.coding.va.selfhelp.presentation.screens.imbue.model.toVortexCard
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class ImbueViewModel(
    private val addImbueToSheet: AddImbue,
    private val canMakeCreation: CanMakeCreation
) : ViewModel() {

    private val _display = MutableStateFlow(ImbueDisplayProvider.provide(false))
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null
    private var isInitialized = false

    fun initVM(actions: MainActions, isPerson: Boolean) {
        viewModelScope.launch {
            if (!isInitialized) {
                _display.emit(ImbueDisplayProvider.provide(isPerson))
                isInitialized = true
            }
        }
        mainActions = actions
    }

    fun onEvent(event: ImbueEvent) {
        viewModelScope.launch {
            when (event) {
                is ImbueEvent.AddImbueResource -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply {
                                        this[_display.value.form.imbueResources.size + 1] =
                                            ImbueResourceForm()
                                    }
                            )
                        )
                    )
                }

                is ImbueEvent.RemoveImbueResource -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply { remove(event.row) }
                            )
                        )
                    )
                }

                is ImbueEvent.AddPowerSupplier -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply {
                                        val size = this[event.resource]?.energySuppliers?.size ?: 1
                                        this[event.resource] = this[event.resource]?.copy(
                                            energySuppliers = (this[event.resource]?.energySuppliers?.toMutableMap() ?: mutableMapOf())
                                                .apply {
                                                    this[size + 1] = ImbueEnergySupplier()
                                                }
                                        ) ?: ImbueResourceForm()
                                    }
                            )
                        )
                    )
                }

                is ImbueEvent.RemovePowerSupplier -> {
                    _display.emit(
                        _display.value.copy(
                            form = _display.value.form.copy(
                                imbueResources = _display.value.form.imbueResources.toMutableMap()
                                    .apply {
                                        this[event.resource] = this[event.resource]?.copy(
                                            energySuppliers = (this[event.resource]?.energySuppliers?.toMutableMap() ?: mutableMapOf())
                                                .apply { remove(event.row) }
                                        ) ?: ImbueResourceForm()
                                    }
                            )
                        )
                    )
                }

                is ImbueEvent.UpdateImbueForm -> {
                    _display.emit(_display.value.copy(form = event.form))
                }

                is ImbueEvent.Back -> {
                    mainActions?.home()
                }

                is ImbueEvent.Verify -> {
                    when {
                        _display.value.form.isValid() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = false,
                                    verifySheet = _display.value.form.toVerifySheet(false, canMakeCreation().getOrNull() ?: false)
                                )
                            )
                        }

                        _display.value.form.meetsMinRequirements() -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    verifySheet = _display.value.form.toVerifySheet(true, canMakeCreation().getOrNull() ?: false)
                                )
                            )
                        }

                        else -> {
                            _display.emit(
                                _display.value.copy(
                                    shouldValidate = true,
                                    errorBox = ImbueDisplayProvider.reguiredError()
                                )
                            )
                        }
                    }
                }

                is ImbueEvent.AddImbue -> {
                    addImbue()
                }

                is ImbueEvent.DismissError -> {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = true,
                            errorBox = null,
                            verifySheet = null,
                        )
                    )
                }
            }
        }
    }

    private fun addImbue() {
        viewModelScope.launch {
            _display.emit(
                _display.value.copy(
                    verifySheet = _display.value.verifySheet?.copy(
                        confirm = _display.value.verifySheet?.confirm?.copy(
                            loading = true
                        )!!
                    )
                )
            )
            addImbueToSheet(_display.value.form)
                .onSuccess {
                    mainActions?.navigate(
                        MainDestinations.Success(
                            data = SuccessData(
                                cardDisplay = _display.value.form.toVortexCard(it.itemId),
                                entryData = it
                            )
                        )
                    )
                }.onFailure {
                    _display.emit(
                        _display.value.copy(
                            shouldValidate = false,
                            verifySheet = null,
                            errorBox = ApiErrorDisplayProvider.error(it.message)
                        )
                    )
                }
        }
    }
}
