package com.coding.va.selfhelp.presentation.screens.success

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.width
import androidx.compose.material.Surface
import androidx.compose.material.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.LocalLifecycleOwner
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.presentation.commoninterface.onCreate
import com.coding.va.selfhelp.presentation.components.Button
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.success.SuccessViewModel.Companion.DELAY
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessDisplay
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessEvent
import com.coding.va.selfhelp.theme.VortexTypography
import com.coding.va.selfhelp.utils.TYPE
import kotlinx.coroutines.delay

@Composable
fun SuccessScreen(
    viewModel: SuccessViewModel,
    mainActions: MainActions,
    successData: SuccessData
) {
    val display by viewModel.display.collectAsState()
    val typography = VortexTypography()

    LocalLifecycleOwner.current.onCreate {
        viewModel.initVM(successData, mainActions)
    }

    LocalLifecycleOwner.current.onCreate(display) {
        if (getPlatform() == TYPE.DESKTOP && display is SuccessDisplay.Data) {
            delay(DELAY)
            mainActions.home()
        }
    }

    when (val data = display) {
        is SuccessDisplay.Data -> SuccessContent(data, viewModel::onEvent)
        is SuccessDisplay.Loading -> SuccessContent(
            data.display,
            viewModel::onEvent,
            isLoading = true
        )

        is SuccessDisplay.Failure -> {
            Surface(modifier = Modifier.fillMaxSize().background(Color.White)) {
                Column(modifier = Modifier.padding(24.dp)) {
                    Text(
                        modifier = Modifier,
                        text = data.title, style = typography.headlineLarge
                    )
                    Text(
                        modifier = Modifier.padding(top = 24.dp),
                        text = data.description,
                        style = typography.titleLarge
                    )
                    Spacer(modifier = Modifier.weight(1f))
                    Row {
                        Spacer(modifier = Modifier.weight(1f))
                        Button(
                            modifier = Modifier.height(50.dp).width(270.dp),
                            onClick = { viewModel.onEvent(SuccessEvent.Retry) }) {
                            Text(text = data.retryButton)
                        }
                    }
                }
            }
        }
    }
}