package com.coding.va.selfhelp.presentation.screens.success

import androidx.compose.ui.text.AnnotatedString
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.withStyle
import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessDisplay
import com.coding.va.selfhelp.theme.vortexRed
import com.coding.va.selfhelp.utils.TYPE
import io.ktor.util.Platform

object SuccessDisplayMapper {

    fun mapSuccess(data: SuccessData?) = SuccessDisplay.Data(
        title = "Vortex Self-help Success!",
        description = buildAnnotatedString {
            append("Please put all resources and energy in an envelope and write '")
            withStyle(style = SpanStyle(color = vortexRed, fontFamily = FontFamily.Serif)) {
                append("${data?.entryData?.itemId}")
            }
            append("' on it. Put the envelope in the self-help box.")
        },
        vortexPrintingCard = data?.cardDisplay,
        doneButton = "Im done here, back to home",
        extraInfo = if (getPlatform() == TYPE.MOBILE) buildAnnotatedString {
            append("You can print your lammy at the Self Help station with card-print-code ")
            withStyle(style = SpanStyle(color = vortexRed, fontFamily = FontFamily.Serif)) {
                append("${data?.entryData?.getCardCode}")
            }
            append("\nThis code is available at the home screen too")
        } else AnnotatedString("")
    )

    fun provideFailure() = SuccessDisplay.Failure(
        title = "Vortex Self-help Failure ):",
        description = "Please check if the printer is turned on and connected, could not find printer",
        retryButton = "Try again",
    )

    fun mapPrinting(data: SuccessData?): SuccessDisplay = SuccessDisplay.Loading(
        mapSuccess(data)
    )

    fun provideLoading(): SuccessDisplay = SuccessDisplay.Loading(
        mapSuccess(null)
    )
}