package com.coding.va.selfhelp.presentation.screens.mainscreen


import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.navigation.NavController
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.rememberNavController
import com.coding.va.selfhelp.presentation.components.onlyDesktop
import com.coding.va.selfhelp.presentation.screens.craft.navigation.CraftItemRoute
import com.coding.va.selfhelp.presentation.screens.imbue.navigation.ImbueRoute
import com.coding.va.selfhelp.presentation.screens.landing.navigation.LandingRoute
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.recharge.navigation.RechargeRoute
import com.coding.va.selfhelp.presentation.screens.success.navigation.SuccessRoute

@Composable
fun MainScreen(
    mainViewModel: MainViewModel,
    onNavHostReady: suspend (NavController) -> Unit = {}
) {
    val navController: NavHostController = rememberNavController()
    val actions = remember {
        MainActions(navController, {})
    }
    val scrollState = rememberScrollState()

    NavHost(
        navController = navController,
        startDestination = MainDestinations.Landing,
        modifier = Modifier
            .fillMaxSize()
            .onlyDesktop {
                padding(horizontal = 14.dp)
            }
            .verticalScroll(scrollState)
    ) {
        LandingRoute(actions)
        CraftItemRoute(actions)
        SuccessRoute(actions)
        ImbueRoute(actions)
        RechargeRoute(actions)
    }

    LaunchedEffect(navController) {
        onNavHostReady(navController)
    }
}