package com.coding.va.selfhelp.presentation.screens.landing

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.coding.va.selfhelp.domain.constants.Constants
import com.coding.va.selfhelp.domain.use_cases.CanMakeCreation
import com.coding.va.selfhelp.domain.use_cases.GetLocalIpAddress
import com.coding.va.selfhelp.domain.use_cases.GetPrintData
import com.coding.va.selfhelp.domain.use_cases.SavedCreationUseCase
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenEvent
import com.coding.va.selfhelp.presentation.screens.landing.model.MenuDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.mainscreen.model.TaskType
import com.russhwolf.settings.Settings
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch


class LandingViewModel(
    private val getLocalIpAddress: GetLocalIpAddress,
    private val getPrintData: GetPrintData,
    private val savedCreationUseCase: SavedCreationUseCase,
    private val canMakeCreation: CanMakeCreation,
) : ViewModel() {

    companion object {
        const val UNLOCK_PASS = "VortexianCookies"
    }

    private val settings = Settings()

    private val _display = MutableStateFlow(
        LandingScreenDisplayProvider.mapLandingDisplay(
            getPrintSetting(),
            savedCreationUseCase.get().getOrNull(), true,
        )
    )
    val display = _display.asStateFlow()

    private val _navigate = MutableSharedFlow<MainDestinations>()
    val navigate = _navigate.asSharedFlow()

    private var menuUnlocked: Boolean = false

    private fun getPrintSetting() = settings.getBoolean(Constants.SETTINGS_KEY_PRINT_CODE, false)

    init {
        viewModelScope.launch {
            _display.emit(
                LandingScreenDisplayProvider.mapLandingDisplay(
                    getPrintSetting(),
                    savedCreationUseCase.get().getOrNull(), canMakeCreation().getOrNull() ?: false,
                )
            )
        }
    }

    fun onEvent(event: LandingScreenEvent) {
        viewModelScope.launch {
            when (event) {
                is LandingScreenEvent.Navigate -> {
                    when (event.type) {
                        TaskType.CreateItem -> _navigate.emit(MainDestinations.CraftItem)
                        TaskType.ImbueItem -> _navigate.emit(MainDestinations.Imbue(isPerson = false))
                        TaskType.ImbuePerson -> _navigate.emit(MainDestinations.Imbue(isPerson = true))
                        TaskType.RechargeItem -> _navigate.emit(MainDestinations.RechargeItem)
                    }
                }

                is LandingScreenEvent.MenuChange -> {
                    when (event.menu) {
                        is MenuDisplay.Locked -> {
                            if (event.menu.password == UNLOCK_PASS) {
                                menuUnlocked = true
                                _display.emit(
                                    _display.value.copy(
                                        menuDisplay = getSettingsMenu()
                                    )
                                )
                            } else {
                                if (!menuUnlocked) {
                                    _display.emit(
                                        _display.value.copy(
                                            menuDisplay = event.menu
                                        )
                                    )
                                }
                            }
                        }

                        is MenuDisplay.UnLocked -> {
                            _display.emit(
                                _display.value.copy(
                                    menuDisplay = event.menu
                                )
                            )
                        }
                    }

                }

                is LandingScreenEvent.MenuSave -> {
                    (display.value.menuDisplay as? MenuDisplay.UnLocked)?.let { menu ->
                        settings.putString(Constants.SETTINGS_KEY_SHEET_ID, menu.sheetId)
                        settings.putString(Constants.SETTINGS_KEY_PRINTER_IP, menu.printerIp)
                        settings.putBoolean(Constants.SETTINGS_KEY_PRINTER_ENABLED, menu.printerEnabled)
                        settings.putBoolean(Constants.SETTINGS_KEY_PRINT_CODE, menu.printerCodeEnabled)
                    }
                }

                is LandingScreenEvent.MenuLock -> {
                    menuUnlocked = false
                    _display.emit(
                        _display.value.copy(
                            menuDisplay = LandingScreenDisplayProvider.provideMenu()
                        )
                    )
                }

                is LandingScreenEvent.CardCode -> {
                    _display.emit(
                        _display.value.copy(
                            cardCode = event.code
                        )
                    )
                }

                is LandingScreenEvent.PrintCard -> {
                    _display.emit(_display.value.copy(attemptPrintButton = _display.value.attemptPrintButton?.copy(loading = true)))
                    getPrintData(_display.value.cardCode)
                        .onSuccess {
                            if (it.entryData.alreadyPrinted) {
                                _display.emit(
                                    _display.value.copy(
                                        errorBox = LandingScreenDisplayProvider.provideAlreadyPrintedError(),
                                        attemptPrintButton = _display.value.attemptPrintButton?.copy(loading = false)
                                    )
                                )
                            } else {
                                _navigate.emit(MainDestinations.Success(it))
                            }
                        }.onFailure {
                            _display.emit(
                                _display.value.copy(
                                    errorBox = LandingScreenDisplayProvider.providePrintError(),
                                    attemptPrintButton = _display.value.attemptPrintButton?.copy(loading = false)
                                )
                            )
                        }
                }

                is LandingScreenEvent.DismissError -> {
                    _display.emit(
                        _display.value.copy(
                            errorBox = null
                        )
                    )
                }
            }
        }
    }

    private suspend fun getSettingsMenu(): MenuDisplay {
        return MenuDisplay.UnLocked(
            header = "Settings Menu",
            printerIpLabel = "Printer IP",
            printerEnabledLabel = "Printer Enabled",
            printerCodeEnabledLabel = "Print card-print-code",
            sheetIpLabel = "Drive Sheet ID",
            deviceIpLabel = "Local IP",
            printerCodeEnabled = settings.getBoolean(Constants.SETTINGS_KEY_PRINT_CODE, false),
            sheetId = settings.getString(Constants.SETTINGS_KEY_SHEET_ID, ""),
            printerIp = settings.getString(Constants.SETTINGS_KEY_PRINTER_IP, ""),
            printerEnabled = settings.getBoolean(Constants.SETTINGS_KEY_PRINTER_ENABLED, true),
            deviceIp = getLocalIpAddress(),
            save = "Save",
            lock = "Lock"
        )
    }
}