import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json

class SuccessViewModel(
    private val printing: PrintingUseCase,
    private val setPrinted: SetPrinted,
    private val savedCreationUseCase: SavedCreationUseCase,
) : ViewModel() {

    companion object {
        const val DELAY = 120000L // 2 minutes
    }

    private val _display = MutableStateFlow(SuccessDisplayMapper.provideLoading())
    val display = _display.asStateFlow()

    private var mainActions: MainActions? = null
    private var data: SuccessData? = null
    private var isInitialized = false
    private var didPrint = false

    fun initVM(data: SuccessData, mainActions: MainActions) {
        this.mainActions = mainActions
        this.data = data
        if (!isInitialized) {
            isInitialized = true
            viewModelScope.launch {
                if (getPlatform() == TYPE.DESKTOP) {
                    _display.emit(SuccessDisplayMapper.mapPrinting(data))
                } else {
                    savedCreationUseCase.set(SavedCreation(data.entryData.getCardCode, data.entryData.type.displayName, data.cardDisplay.getEasyName(data.entryData.type))).onFailure {
                        println("Error saving creation: $it")
                    }.getOrNull()
                    _display.emit(SuccessDisplayMapper.mapSuccess(data))
                }
            }
        }
    }

    fun onEvent(event: SuccessEvent) {
        viewModelScope.launch {
            when (event) {
                is SuccessEvent.PrintCard -> {
                    if (!didPrint) {
                        printing.printImage(event.card).onSuccess {
                            didPrint = true
                            _display.emit(SuccessDisplayMapper.mapSuccess(data))
                            data?.entryData?.let {
                                setPrinted(it).getOrNull()
                            }
                        }.onFailure {
                            _display.emit(SuccessDisplayMapper.provideFailure())
                        }
                    } else {
                        _display.emit(SuccessDisplayMapper.mapSuccess(data))
                    }
                }

                is SuccessEvent.Close -> {
                    mainActions?.home()
                }

                is SuccessEvent.Retry -> {
                    _display.emit(SuccessDisplayMapper.mapPrinting(data))
                }
            }
        }
    }
}
