@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun VerifySheet(
    display: VerifySheetDisplay,
    onDismiss: (() -> Unit)? = null,
    onConfirm: (() -> Unit)? = null
) {
    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)
    val scope = rememberCoroutineScope()
    var showBottomSheet by remember { mutableStateOf(true) }

    ModalBottomSheet(
        modifier = Modifier.onlyDesktop { fillMaxWidth(0.5f) },
        onDismissRequest = {
            showBottomSheet = false
            onDismiss?.invoke()
        },
        sheetState = sheetState,
    ) {
        VerifySheetContent(
            display = display,
            onDismiss = {
                scope.launch { sheetState.hide() }.invokeOnCompletion {
                    if (!sheetState.isVisible) {
                        showBottomSheet = false
                        onDismiss?.invoke()
                    }
                }
            },
            onConfirm = {
                onConfirm?.invoke()
            }
        )
    }
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun VerifySheetContent(
    display: VerifySheetDisplay,
    onDismiss: (() -> Unit),
    onConfirm: (() -> Unit)
) {
    val typography = VortexTypography()
    Column(
        modifier = Modifier.fillMaxWidth()
            .onlyDesktop { fillMaxHeight(0.75f) }
            .onlyMobile { fillMaxHeight(0.90f) }
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 32.dp)
            .padding(bottom = 32.dp)
    ) {
        Text(text = display.title, style = typography.titleLarge)
        Text(modifier = Modifier.padding(top = 8.dp), text = display.description, style = typography.bodyMedium)

        Text(modifier = Modifier.padding(top = 12.dp), text = display.resourcesLabel, style = typography.bodyLarge)
        Text(modifier = Modifier.padding(top = 8.dp), text = display.resources, style = typography.bodyMedium)

        Text(modifier = Modifier.padding(top = 12.dp, bottom = 12.dp), text = display.lammyLabel, style = typography.bodyLarge)

        if (getPlatform() == TYPE.DESKTOP) {
            Row(
                modifier = Modifier.height(200.dp).fillMaxWidth(),
                horizontalArrangement = Arrangement.Center
            ) {
                VortexItemCardUIFront(display = display.lammy, modifier = Modifier.fillMaxHeight())
                Spacer(modifier = Modifier.width(32.dp))
                VortexItemCardUIBack(display = display.lammy, modifier = Modifier.fillMaxHeight())
            }
        } else {
            FlowRow(horizontalArrangement = Arrangement.Center) {
                VortexItemCardUIFront(display = display.lammy, modifier = Modifier.fillMaxWidth())
                VortexItemCardUIBack(display = display.lammy, modifier = Modifier.fillMaxWidth())
            }
        }

        Spacer(modifier = Modifier.weight(1f))
        Row(modifier = Modifier.padding(top = 24.dp)) {
            Button(
                modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                onClick = { onDismiss() }) {
                Text(text = display.dismiss)
            }
            Spacer(modifier = Modifier.weight(1f))
            Button(
                modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                onClick = { onConfirm() },
                enabled = !display.confirm.loading && display.confirm.enabled,
            ) {
                Text(text = display.confirm.label)
            }
        }
    }
}
