package com.coding.va.selfhelp.presentation.screens.recharge.navigation

import androidx.navigation.NavGraphBuilder
import androidx.navigation.compose.composable
import androidx.navigation.toRoute
import com.coding.va.selfhelp.presentation.methods.GenericNavType
import com.coding.va.selfhelp.presentation.screens.imbue.ImbueScreen
import com.coding.va.selfhelp.presentation.screens.mainscreen.actions.MainActions
import com.coding.va.selfhelp.presentation.screens.mainscreen.destinations.MainDestinations
import com.coding.va.selfhelp.presentation.screens.recharge.RechargeScreen
import com.coding.va.selfhelp.presentation.screens.success.SuccessScreen
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import org.koin.compose.koinInject
import kotlin.reflect.typeOf

fun NavGraphBuilder.RechargeRoute(action: MainActions) {
    composable<MainDestinations.RechargeItem>(
        typeMap = mapOf(
            typeOf<MainDestinations.RechargeItem>() to GenericNavType(MainDestinations.RechargeItem.serializer())
        )
    ) {
        RechargeScreen(koinInject(), action)
    }
}
