package com.coding.va.selfhelp.presentation.screens.landing

import com.coding.va.selfhelp.di.getPlatform
import com.coding.va.selfhelp.domain.use_cases.CanMakeCreation
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.methods.LoadingButtonDisplay
import com.coding.va.selfhelp.presentation.methods.SavedCreations
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenEvent
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenDisplay
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenRecentCreationsDisplay
import com.coding.va.selfhelp.presentation.screens.landing.model.LandingScreenTask
import com.coding.va.selfhelp.presentation.screens.landing.model.MenuDisplay
import com.coding.va.selfhelp.presentation.screens.mainscreen.model.TaskType
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay
import com.coding.va.selfhelp.utils.TYPE

object LandingScreenDisplayProvider {

    fun mapLandingDisplay(printFieldEnabled: Boolean, savedCreations: SavedCreations?, canMakeCreation: Boolean) = LandingScreenDisplay(
        title = "Vortex Adventures Self-help",
        description = "Please choose what you would like to accomplish",
        serviceMessage = if (!canMakeCreation) "It's not 'Tijd In'.\nyou can browse around but you cannot create anything right now" else null,
        tasks = listOf(
            LandingScreenTask(
                title = "Craft Item",
                taskType = TaskType.CreateItem,
                action = LandingScreenEvent.Navigate(TaskType.CreateItem)
            ),
            LandingScreenTask(
                title = "Imbue Item",
                taskType = TaskType.ImbueItem,
                action = LandingScreenEvent.Navigate(TaskType.ImbueItem)
            ),
            LandingScreenTask(
                title = "Imbue Person",
                taskType = TaskType.ImbuePerson,
                action = LandingScreenEvent.Navigate(TaskType.ImbuePerson)
            ),
            LandingScreenTask(
                title = "Recharge Item",
                taskType = TaskType.RechargeItem,
                action = LandingScreenEvent.Navigate(TaskType.RechargeItem)
            )
        ),
        menuDisplay = provideMenu(),
        printField = if (printFieldEnabled) {
            FieldDisplay("Code", "enter your card-print-code to print your card")
        } else null,
        cardCode = "",
        printDescription = "if you have a card-print-code from a mobile device, enter it here to print your card",
        attemptPrintButton = LoadingButtonDisplay("Print", false, true),
        errorBox = null,
        recentCreations = if (getPlatform() == TYPE.MOBILE) {
            savedCreations?.items?.let {
                LandingScreenRecentCreationsDisplay(
                    "card-print-code overview of your recent creations.\ngo to the selfhelp to print your card",
                    it.takeLast(10)
                )
            }
        } else null
    )

    fun provideMenu() = MenuDisplay.Locked(
        header = "Settings Menu",
        passwordLabel = "password to unlock",
        password = ""
    )

    fun providePrintError() = ErrorBoxDisplay(
        title = "Not found",
        description = "Please enter a valid card-print-code",
        retryButton = "Ok",
        acceptButton = null,
    )

    fun provideAlreadyPrintedError() = ErrorBoxDisplay(
        title = "Nope!",
        description = "This item has already been printed!",
        retryButton = "Ok",
        acceptButton = null,
    )
}