package com.coding.va.selfhelp.domain.use_cases

import com.coding.va.selfhelp.domain.respository.SheetsRepository
import com.coding.va.selfhelp.presentation.screens.model.VortexItemCardDisplay
import com.coding.va.selfhelp.presentation.screens.success.model.SuccessData
import org.koin.core.component.KoinComponent


class GetPrintData(private val geminiRepository: SheetsRepository) : KoinComponent {

    suspend operator fun invoke(cardCode: String): Result<SuccessData> {
        return geminiRepository.getPrintData(cardCode)
    }
}