package com.coding.va.selfhelp.presentation.screens.craft

import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.ExperimentalLayoutApi
import androidx.compose.foundation.layout.FlowRow
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.Spacer
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.width
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.Surface
import androidx.compose.material.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import com.coding.va.selfhelp.domain.model.CraftingResource
import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.presentation.commoninterface.ceil
import com.coding.va.selfhelp.presentation.commoninterface.orZero
import com.coding.va.selfhelp.presentation.commoninterface.toIntOrZero
import com.coding.va.selfhelp.presentation.components.Button
import com.coding.va.selfhelp.presentation.components.OutlinedTextField
import com.coding.va.selfhelp.presentation.components.errorbox.ErrorBox
import com.coding.va.selfhelp.presentation.components.moveFocusOnTab
import com.coding.va.selfhelp.presentation.components.onlyDesktop
import com.coding.va.selfhelp.presentation.components.plinfield.PlinTextField
import com.coding.va.selfhelp.presentation.components.selectablefield.SelectableField
import com.coding.va.selfhelp.presentation.screens.craft.model.CraftItemDisplay
import com.coding.va.selfhelp.presentation.screens.craft.model.CraftItemEvent
import com.coding.va.selfhelp.presentation.screens.craft.model.getResourcesImbueCap
import com.coding.va.selfhelp.presentation.screens.craft.model.isDescriptionValid
import com.coding.va.selfhelp.presentation.screens.craft.model.isEnergyAmountValid
import com.coding.va.selfhelp.presentation.screens.craft.model.isImbueCapValid
import com.coding.va.selfhelp.presentation.screens.craft.model.isPlinValid
import com.coding.va.selfhelp.presentation.screens.craft.model.isResourceAmountValid
import com.coding.va.selfhelp.presentation.screens.craft.model.isResourceTypeValid
import com.coding.va.selfhelp.presentation.screens.craft.model.isTitleValid
import com.coding.va.selfhelp.presentation.screens.verify.VerifySheet
import com.coding.va.selfhelp.theme.VortexTypography

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun CraftItemContent(
    display: CraftItemDisplay,
    onEvent: ((CraftItemEvent) -> Unit)? = null
) {
    val numberRegex = remember { Regex("^\\d+\$") }
    val typography = VortexTypography()

    Surface(modifier = Modifier.fillMaxSize().background(Color.White)) {
        display.errorBox?.let {
            ErrorBox(
                display = it,
                onConfirmation = { onEvent?.invoke(CraftItemEvent.AddItem) },
                onDismissRequest = { onEvent?.invoke(CraftItemEvent.DismissError) })
        }

        display.verifySheet?.let {
            VerifySheet(
                display = it,
                onConfirm = { onEvent?.invoke(CraftItemEvent.AddItem) },
                onDismiss = { onEvent?.invoke(CraftItemEvent.DismissError) }
            )
        }

        Column(modifier = Modifier.padding(24.dp)) {
            Text(text = display.title, style = typography.headlineLarge)
            Text(text = display.description, style = typography.titleLarge)

            Column(modifier = Modifier.padding(top = 24.dp)) {
                OutlinedTextField(
                    modifier = Modifier.moveFocusOnTab(),
                    isError = display.shouldValidate && !display.form.isTitleValid(),
                    value = display.form.name,
                    placeholder = { Text(text = display.itemTitle.hint) },
                    onValueChange = {
                        onEvent?.invoke(
                            CraftItemEvent.UpdateCraftForm(
                                display.form.copy(
                                    name = it
                                )
                            )
                        )
                    },
                    label = { Text(text = display.itemTitle.label) }
                )
                OutlinedTextField(
                    modifier = Modifier.moveFocusOnTab(),
                    isError = display.shouldValidate && !display.form.isDescriptionValid(),
                    value = display.form.description,
                    placeholder = { Text(text = display.itemDescription.hint) },
                    onValueChange = {
                        onEvent?.invoke(
                            CraftItemEvent.UpdateCraftForm(
                                display.form.copy(
                                    description = it
                                )
                            )
                        )
                    },
                    label = { Text(text = display.itemDescription.label) }
                )
                Row(verticalAlignment = Alignment.CenterVertically) {
                    OutlinedTextField(
                        modifier = Modifier.width(150.dp).moveFocusOnTab(),
                        isError = display.shouldValidate && !display.form.isImbueCapValid(),
                        value = display.form.imbueCap,
                        placeholder = { Text(text = display.itemImbueCap.hint) },
                        onValueChange = {
                            if (it.isEmpty() || it.matches(numberRegex)) {
                                onEvent?.invoke(
                                    CraftItemEvent.UpdateCraftForm(
                                        display.form.copy(
                                            imbueCap = it
                                        )
                                    )
                                )
                            }
                        },
                        label = { Text(text = display.itemImbueCap.label) }
                    )
                    display.form.getResourcesImbueCap().let {
                        if (it > 0) {
                            Text(
                                modifier = Modifier.padding(start = 8.dp),
                                text = "currently from resources: $it",
                                style = typography.bodyMedium
                            )
                        }
                    }
                }
                OutlinedTextField(
                    modifier = Modifier.height(100.dp).width(350.dp).moveFocusOnTab(),
                    value = display.form.notes,
                    placeholder = { Text(text = display.itemNotes.hint) },
                    onValueChange = {
                        onEvent?.invoke(
                            CraftItemEvent.UpdateCraftForm(
                                display.form.copy(
                                    notes = it
                                )
                            )
                        )
                    },
                    label = { Text(text = display.itemNotes.label) }
                )
                Text(
                    modifier = Modifier.padding(top = 16.dp, bottom = 16.dp),
                    text = display.resourceDescription,
                    style = typography.bodyMedium
                )
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    display.form.resources.forEach { entry ->
                        FlowRow(verticalArrangement = Arrangement.Bottom) {
                            FlowRow(
                                modifier = Modifier.border(3.dp, Color.Black, RoundedCornerShape(8.dp))
                                    .padding(top = 16.dp, start = 16.dp, end = 16.dp, bottom = 20.dp),
                            ) {

                                SelectableField(
                                    modifier = Modifier.width(200.dp).padding(start = 8.dp)
                                        .moveFocusOnTab(),
                                    isError = display.shouldValidate && !entry.value.isResourceTypeValid(),
                                    display = display.itemCraftResource.resourceType,
                                    value = entry.value.resourceType?.resourceName,
                                    onSelected = {
                                        onEvent?.invoke(
                                            CraftItemEvent.UpdateCraftForm(
                                                display.form.copy(
                                                    resources = display.form.resources.toMutableMap()
                                                        .apply {
                                                            val resource =
                                                                CraftingResource.valueOf(it.id)
                                                            this[entry.key] = entry.value.copy(
                                                                resourceType = resource,
                                                                energyAmount = (resource.requiredEnergy * entry.value.resourceAmount.toIntOrZero()).ceil()
                                                                    .toString()
                                                            )
                                                        }
                                                )
                                            )
                                        )
                                    }
                                )

                                OutlinedTextField(
                                    modifier = Modifier.width(150.dp).padding(start = 8.dp)
                                        .moveFocusOnTab(),
                                    isError = display.shouldValidate && !entry.value.isResourceAmountValid(),
                                    value = display.form.resources[entry.key]?.resourceAmount ?: "",
                                    placeholder = { Text(text = display.itemCraftResource.resourceAmount.hint) },
                                    onValueChange = {
                                        if (it.isEmpty() || it.matches(numberRegex)) {
                                            onEvent?.invoke(
                                                CraftItemEvent.UpdateCraftForm(
                                                    display.form.copy(
                                                        resources = display.form.resources.toMutableMap()
                                                            .apply {
                                                                this[entry.key] = entry.value.copy(
                                                                    resourceAmount = it,
                                                                    energyAmount = ((entry.value.resourceType?.requiredEnergy.orZero()) * it.toIntOrZero()).ceil()
                                                                        .toString()
                                                                )
                                                            }
                                                    )
                                                )
                                            )
                                        }
                                    },
                                    label = { Text(text = display.itemCraftResource.resourceAmount.label) }
                                )

                                OutlinedTextField(
                                    modifier = Modifier.width(150.dp).padding(start = 8.dp)
                                        .moveFocusOnTab(),
                                    isError = display.shouldValidate && !entry.value.isEnergyAmountValid(),
                                    value = entry.value.energyAmount,
                                    placeholder = { Text(text = display.itemCraftResource.energyAmount.hint) },
                                    onValueChange = {
                                        if (it.isEmpty() || it.matches(numberRegex)) {
                                            onEvent?.invoke(
                                                CraftItemEvent.UpdateCraftForm(
                                                    display.form.copy(
                                                        resources = display.form.resources.toMutableMap()
                                                            .apply {
                                                                this[entry.key] = entry.value.copy(
                                                                    energyAmount = it
                                                                )
                                                            }
                                                    )
                                                )
                                            )
                                        }
                                    },
                                    label = { Text(text = display.itemCraftResource.energyAmount.label) }
                                )

                                SelectableField(
                                    modifier = Modifier.width(200.dp).padding(start = 8.dp)
                                        .moveFocusOnTab(),
                                    isError = display.shouldValidate && !entry.value.isResourceTypeValid(),
                                    display = display.itemCraftResource.energyType,
                                    value = entry.value.energyType.displayName,
                                    onSelected = {
                                        onEvent?.invoke(
                                            CraftItemEvent.UpdateCraftForm(
                                                display.form.copy(
                                                    resources = display.form.resources.toMutableMap()
                                                        .apply {
                                                            this[entry.key] = entry.value.copy(
                                                                energyType = EnergyType.valueOf(it.id)
                                                            )
                                                        }
                                                )
                                            )
                                        )
                                    }
                                )

                                PlinTextField(
                                    display = display.itemCraftResource.plin,
                                    modifier = Modifier.padding(start = 8.dp)
                                        .moveFocusOnTab(),
                                    isError = display.shouldValidate && !entry.value.isPlinValid(),
                                    value = entry.value.plin,
                                    onValueChange = {
                                        onEvent?.invoke(
                                            CraftItemEvent.UpdateCraftForm(
                                                display.form.copy(
                                                    resources = display.form.resources.toMutableMap()
                                                        .apply {
                                                            this[entry.key] = entry.value.copy(
                                                                plin = it
                                                            )
                                                        }
                                                )
                                            )
                                        )
                                    },
                                )


                            }
                            if (display.form.resources.size == entry.key) {
                                FlowRow {
                                    if (entry.key > 1) {
                                        Button(
                                            modifier = Modifier.padding(top = 10.dp, start = 12.dp)
                                                .height(50.dp)
                                                .width(50.dp),
                                            onClick = { onEvent?.invoke(CraftItemEvent.RemoveResourceRow(entry.key)) }) {
                                            Text(text = "-")
                                        }
                                    }
                                    Button(
                                        modifier = Modifier.padding(top = 10.dp, start = 12.dp)
                                            .height(50.dp)
                                            .width(50.dp),
                                        onClick = { onEvent?.invoke(CraftItemEvent.AddResourceRow) }) {
                                        Text(text = "+")
                                    }
                                }
                            }
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.weight(1f))
            Row(modifier = Modifier.padding(top = 24.dp)) {
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(CraftItemEvent.Back) }) {
                    Text(text = "Back to Home")
                }
                Spacer(modifier = Modifier.weight(1f))
                Button(
                    modifier = Modifier.height(50.dp).onlyDesktop { width(200.dp) },
                    onClick = { onEvent?.invoke(CraftItemEvent.Verify) }) {
                    Text(text = "Next - Verify Item")
                }
            }
        }
    }
}


