package com.coding.va.selfhelp.presentation.components.plinfield

import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.offset
import androidx.compose.foundation.layout.width
import com.coding.va.selfhelp.presentation.components.OutlinedTextField
import androidx.compose.material.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.focus.FocusRequester
import androidx.compose.ui.focus.focusRequester
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import com.coding.va.selfhelp.presentation.components.moveFocusOnTab
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay

@Composable
fun PlinTextField(
    display: PlinFieldDisplay,
    value: Pair<String, String> = Pair("", ""),
    isError: Boolean = false,
    onValueChange: (Pair<String, String>) -> Unit = {},
    modifier: Modifier = Modifier,
    plinWidth: Dp = 100.dp
) {
    val numberRegex = remember { Regex("^\\d+\$") }

    Row(modifier = modifier) {
        val plinFocusRequester = remember { FocusRequester() }
        val chinFocusRequester = remember { FocusRequester() }

        OutlinedTextField(
            modifier = Modifier.width(plinWidth)
                .focusRequester(plinFocusRequester)
                .moveFocusOnTab(),
            isError = isError,
            value = value.first,
            placeholder = { Text(text = display.plinHint) },
            enabled = display.enabled,
            onValueChange = {
                if (it.isEmpty() || it.matches(numberRegex)) {
                    onValueChange(value.copy(first = it))
                }
                if (it.length == 4) {
                    chinFocusRequester.requestFocus()
                }
            },
            label = { Text(text = display.plinLabel) }
        )
        OutlinedTextField(
            modifier = Modifier.width(75.dp)
                .focusRequester(chinFocusRequester)
                .offset(x = (-1f).dp)
                .moveFocusOnTab(),
            isError = isError,
            value = value.second,
            placeholder = { Text(text = display.chinHint) },
            enabled = display.enabled,
            onValueChange = {
                if (it.isEmpty() || it.matches(numberRegex)) {
                    onValueChange(value.copy(second = it))
                }
                if (it.isEmpty()) {
                    plinFocusRequester.requestFocus()
                }
            },
            label = { Text(text = display.chinLabel) }
        )
    }
}