package com.coding.va.selfhelp.presentation.screens.imbue

import com.coding.va.selfhelp.domain.model.EnergyType
import com.coding.va.selfhelp.presentation.components.errorbox.model.ErrorBoxDisplay
import com.coding.va.selfhelp.presentation.components.plinfield.model.PlinFieldDisplay
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldContent
import com.coding.va.selfhelp.presentation.components.selectablefield.model.SelectableFieldDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueForm
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueResourceDisplay
import com.coding.va.selfhelp.presentation.screens.imbue.model.ImbueResourceForm
import com.coding.va.selfhelp.presentation.screens.model.FieldDisplay

object ImbueDisplayProvider {

    fun provide(isPerson: Boolean) = ImbueDisplay(
        title = if (isPerson) "Imbue a Person" else "Imbue an Item",
        description = "Please fill in the form below to start your imbue",
        imbueDescription = if (isPerson) "To place a imbue on a person there should be enough space in their personal imbue cap, you can replace an existing imbue by making a note about it in the 'special notes' section.\nThe skill should also be available to the main imbuer who places the imbue as described in the loresheet.\nLastly put the energy in a envelope and write the imbueID of your imbue on it (found on the next page), Please also write the PLIN of the imbuer on the energy"
        else "To place an imbue on an item there should be enough space on the item's imbue cap, you can replace an existing imbue by making a note about it in the 'special notes' section.\nThe skill should also be available to the main imbuer who places the imbue as described in the loresheet.\nLastly put the energy in an envelope and write the imbueID of your imbue on it (found on the next page), Please also write the PLIN of the imbuer on the energy",
        isPerson = isPerson,
        imbueNotes = FieldDisplay(
            label = "Special Notes",
            hint = "Anything else we need to know to process your creation, special items used etc"
        ),
        imbueTarget = if (isPerson) {
            PlinFieldDisplay(
                plinLabel = "Receiver PLIN",
                plinHint = "PLIN of the receiver of the Imbue",
                chinLabel = "CHIN",
                chinHint = "CHIN"
            )
        } else {
            PlinFieldDisplay(
                plinLabel = "Item ITIN",
                plinHint = "ITIN of the item to imbue",
                chinLabel = "",
                chinHint = ""
            )
        },
        imbueResource = provideEmptyImbueResource(isPerson),
        form = ImbueForm(
            isPerson = isPerson,
            targetItin = if (isPerson) null else "",
            targetPlin = if (isPerson) Pair("", "") else null,
            notes = "",
            imbueResources = mutableMapOf(1 to ImbueResourceForm())
        ),
        shouldValidate = false,
        errorBox = null,
        imbueEffectNumber = "imbue effect ",
        validate = "Next - Verify Imbue",
        verifySheet = null,
    )

    fun provideEmptyImbueResource(isPerson: Boolean) = ImbueResourceDisplay(
        imbueType = SelectableFieldDisplay(
            label = "Select Imbue",
            content = ImbueTypes.getAllImbueTypes(isPerson).map {
                SelectableFieldContent(
                    it.displayName,
                    it.id
                )
            }
        ),
        imbueOption = SelectableFieldDisplay(
            label = "Select Options",
            enabled = false,
            content = emptyList()
        ),
        amount = FieldDisplay(label = "Amount", hint = " how many of this imbue"),
        energyAmount = FieldDisplay(
            label = "Energy",
            hint = "how much mana / inspiration etc",
            enabled = false
        ),
        skillSpell = FieldDisplay(
            label = "Skill/Spell",
            hint = "name of the skill/spell you want to imbue",
            visible = false,
        ),
        custom = FieldDisplay(
            label = "Custom Imbue Name",
            hint = "enter the name of the custom imbue",
            visible = false,
        ),
        energyType = SelectableFieldDisplay(
            label = "Select Energy Type",
            content = EnergyType.entries.map {
                SelectableFieldContent(
                    it.displayName,
                    it.name
                )
            }
        ),
        plin = PlinFieldDisplay(
            plinLabel = "PLIN",
            plinHint = "PLIN of the main imbuer who knows this ability",
            chinLabel = "CHIN",
            chinHint = ""
        ),
        energySupplierDescription = "Who is supplying the energy for this imbue, it needs to be in ",
        energySupplierAmount = FieldDisplay(
            label = "Amount",
            hint = "How much does this person supply",
        ),
        energySupplierPlin = PlinFieldDisplay(
            plinLabel = "PLIN",
            plinHint = "PLIN of the energy supplier",
            chinLabel = "CHIN",
            chinHint = ""
        )
    )

    fun reguiredError() = ErrorBoxDisplay(
        title = "This is not right",
        description = "please finish filling in the form first",
        acceptButton = null,
        retryButton = "Alright, let me do that"
    )
}